html:
{%- set company = frappe.get_doc("Company", doc.company) if doc.company else None -%}
{%- set so = frappe.get_doc("Sales Order", doc.sales_order) -%}
{%- set bank = frappe.get_doc("Bank Account", doc.bank_account) if doc.bank_account else None -%}
{%- set rows = doc.items if doc.items else so.get("items") -%}
<style>
  .ef-pfi { font-family: Helvetica, Arial, sans-serif; font-size: 12px; color: #1a2030; line-height: 1.5; }
  .ef-pfi h1 { font-size: 20px; letter-spacing: .14em; margin: 0 0 2px; }
  .ef-pfi .muted { color: #586273; }
  .ef-pfi .head { display: flex; justify-content: space-between; align-items: flex-start; border-bottom: 2px solid #1a2030; padding-bottom: 10px; margin-bottom: 14px; }
  .ef-pfi .mono { font-family: Menlo, Consolas, monospace; }
  .ef-pfi table.meta { width: 100%; border-collapse: collapse; margin-bottom: 14px; }
  .ef-pfi table.meta td { vertical-align: top; padding: 0 8px 0 0; width: 50%; }
  .ef-pfi .blk { border: 1px solid #dcdfe6; padding: 9px 11px; min-height: 80px; }
  .ef-pfi .blk .lbl { font-size: 9.5px; text-transform: uppercase; letter-spacing: .08em; color: #586273; margin-bottom: 4px; }
  .ef-pfi table.items { width: 100%; border-collapse: collapse; margin: 6px 0 0; }
  .ef-pfi table.items th { text-align: left; font-size: 10px; text-transform: uppercase; letter-spacing: .06em; border-top: 1px solid #1a2030; border-bottom: 1px solid #1a2030; padding: 6px 8px; }
  .ef-pfi table.items td { border-bottom: 1px solid #e7e9ee; padding: 6px 8px; }
  .ef-pfi table.items .r { text-align: right; }
  .ef-pfi .totals { margin-top: 8px; width: 100%; }
  .ef-pfi .totals td { padding: 3px 8px; }
  .ef-pfi .totals .grand { font-weight: bold; font-size: 14px; border-top: 2px solid #1a2030; }
  .ef-pfi .foot { margin-top: 22px; display: flex; justify-content: space-between; gap: 20px; }
  .ef-pfi .sig { margin-top: 56px; border-top: 1px solid #1a2030; width: 220px; padding-top: 4px; font-size: 10.5px; }
</style>
<div class="ef-pfi">
  <div class="head">
    <div>
      <h1>PRO FORMA INVOICE</h1>
      <div class="muted">This is not a tax invoice — issued for advance payment / LC establishment</div>
    </div>
    <div style="text-align:right">
      <div class="mono" style="font-size:14px"><b>{{ doc.name }}</b></div>
      <div class="muted">Date: <span class="mono">{{ frappe.utils.formatdate(doc.pfi_date, "dd MMM yyyy") }}</span></div>
      {% if doc.stage_description %}<div class="muted">{{ doc.stage_description }}</div>{% endif %}
    </div>
  </div>

  <table class="meta"><tr>
    <td><div class="blk">
      <div class="lbl">Exporter</div>
      <b>{{ company.company_name if company else doc.company }}</b><br>
      {% if company and company.get("gstin") %}GSTIN: <span class="mono">{{ company.gstin }}</span><br>{% endif %}
      {% if company and company.get("iec") %}IEC: <span class="mono">{{ company.iec }}</span><br>{% endif %}
    </div></td>
    <td><div class="blk">
      <div class="lbl">Buyer</div>
      <b>{{ doc.customer_name or doc.customer }}</b><br>
      <span class="muted">Sales order:</span> <span class="mono">{{ doc.sales_order }}</span><br>
      {% if so.incoterm %}<span class="muted">Incoterm:</span> {{ so.incoterm }}{% if so.named_place %} · {{ so.named_place }}{% endif %}<br>{% endif %}
      {% if doc.expected_payment_method %}<span class="muted">Payment by:</span> {{ doc.expected_payment_method }}{% endif %}
    </div></td>
  </tr></table>

  {% if doc.basis == "Percentage of SO" %}
  <div class="muted" style="margin-bottom:6px">Stage value: {{ doc.get_formatted("percentage") }}% of sales order value {{ frappe.utils.fmt_money(so.grand_total, currency=doc.currency) }}</div>
  {% endif %}

  <table class="items">
    <thead><tr><th style="width:28px">#</th><th>Description</th><th class="r">Qty</th><th class="r">Rate</th><th class="r">Amount ({{ doc.currency }})</th></tr></thead>
    <tbody>
    {% if rows %}
      {% for row in rows %}
      <tr>
        <td class="mono">{{ loop.index }}</td>
        <td><b>{{ row.item_name or row.item_code }}</b></td>
        <td class="r mono">{{ frappe.utils.flt(row.qty) }} {{ row.uom or "" }}</td>
        <td class="r mono">{{ frappe.utils.fmt_money(row.rate, currency=doc.currency) }}</td>
        <td class="r mono">{{ frappe.utils.fmt_money(row.amount, currency=doc.currency) }}</td>
      </tr>
      {% endfor %}
    {% else %}
      <tr><td class="mono">1</td><td>As per sales order <span class="mono">{{ doc.sales_order }}</span></td><td class="r">—</td><td class="r">—</td><td class="r mono">{{ frappe.utils.fmt_money(doc.amount, currency=doc.currency) }}</td></tr>
    {% endif %}
    </tbody>
  </table>

  <table class="totals"><tr>
    <td></td>
    <td style="width:45%">
      <table style="width:100%">
        <tr class="grand"><td class="grand">Amount payable</td><td class="grand r mono" style="text-align:right">{{ frappe.utils.fmt_money(doc.amount, currency=doc.currency) }}</td></tr>
        <tr><td class="muted" colspan="2" style="font-size:10.5px">{{ frappe.utils.money_in_words(doc.amount, doc.currency) }}</td></tr>
      </table>
    </td>
  </tr></table>

  <div class="foot">
    <div style="flex:1">
      {% if bank %}
      <div class="blk">
        <div class="lbl">Remit to</div>
        <b>{{ bank.account_name }}</b>{% if bank.bank %} · {{ bank.bank }}{% endif %}<br>
        {% if bank.bank_account_no %}A/c no: <span class="mono">{{ bank.bank_account_no }}</span><br>{% endif %}
        {% if bank.iban %}IBAN: <span class="mono">{{ bank.iban }}</span><br>{% endif %}
        {% if bank.get("branch_code") %}SWIFT/IFSC: <span class="mono">{{ bank.branch_code }}</span>{% endif %}
      </div>
      {% endif %}
      {% if doc.terms %}<div style="margin-top:10px; white-space:pre-wrap">{{ doc.terms | e }}</div>{% endif %}
    </div>
    <div>
      <div class="muted" style="font-size:10.5px">For {{ company.company_name if company else doc.company }}</div>
      <div class="sig">Authorised signatory</div>
    </div>
  </div>
</div>
